  const limit = Math.min(Number(ctx.query.get("limit") ?? 50) || 50, 200);
  const rows = await orgTx(
    ctx,
    (tx) => tx.query(
      `select j.*, vr.passed
         from compile_jobs j
         left join verification_reports vr on vr.job_id = j.id
        where ($1::uuid is null or j.project_id = $1::uuid)
        order by j.started_at desc
        limit $2`,
      [projectId, limit]
    )
  );
